// PMS → CRS register: "Read the answer"              (workflow: PMS answer · CRS register)
// Mode: Run Once for All Items.
//
// The hotel's answer on a CRS booking (D27-102, D27-106): Confirmed, or
// Cancelled when the hotel refused it or was full. Written into the booking
// register the CRS's Register screen shows, so the salesperson sees it. The
// PMS decides; this only writes. Nothing else in the CRS changes.
//
// ── THE OWNER'S SETTINGS: edit these, nothing below them ────────────────────
// The booking register's address: copy it from the existing CRS workflow's
// "Add to booking register" node (it ends in /rest/v1/bookings). Until it is
// filled in, every answer is refused with a sentence the PMS shows.
const REGISTER_URL = "";
// The words the Register screen shows for each answer.
const STATUS = { confirmed: "Confirmed", refused: "Cancelled", full: "Cancelled" };
// How long an answer's id is remembered, so a retry is not written twice.
const KEEP_DAYS = 30;
// ─────────────────────────────────────────────────────────────────────────────

const a = $input.first().json.body ?? {};
const stop = (statusCode, answer) => [{ json: { stop: true, statusCode, answer } }];
const text = (v, most) => (typeof v === "string" && v.trim() && v.length <= most ? v.trim() : null);

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(a.messageId ?? "")) {
  return stop(400, { ok: false, error: "No message id." });
}
const memory = $getWorkflowStaticData("global");
memory.written = memory.written ?? {};
const now = Date.now();
for (const [id, at] of Object.entries(memory.written)) {
  if (now - at > KEEP_DAYS * 86400000) delete memory.written[id];
}
if (memory.written[a.messageId]) return stop(200, { ok: true, duplicate: true });

const reference = text(a.crsReference, 40);
if (!reference || !/^[A-Za-z0-9-]+$/.test(reference)) {
  return stop(400, { ok: false, error: "No CRS booking number." });
}
if (!Object.hasOwn(STATUS, a.answer)) return stop(400, { ok: false, error: "No answer." });
if (!REGISTER_URL) {
  return stop(503, { ok: false, error: "The register's address is not filled in in this workflow yet." });
}

return [{ json: {
  stop: false,
  messageId: a.messageId,
  reference,
  status: STATUS[a.answer],
  confirmation: a.answer === "confirmed" ? text(a.hotelConfirmationNumber, 200) : null,
  note: text(a.note, 300),
  findUrl: `${REGISTER_URL}?fidato_conf_no=eq.${encodeURIComponent(reference)}`
    + "&select=id,booking_status,hotel_conf_no,amendment_notes",
  registerUrl: REGISTER_URL,
} }];

// PMS → CRS register: "What to write"
// Mode: Run Once for All Items.
//
// Input: the register row(s) carrying this CRS booking number. The number is
// unique in the register (the existing workflow's own index), so one row or
// none. The status and the hotel's confirmation number are set; the PMS's
// sentence is ADDED to the notes, never written over what somebody typed.

const a = $("Read the answer").first().json;
const res = $input.first().json;
const stop = (statusCode, answer) => [{ json: { stop: true, statusCode, answer } }];

if (!(res.statusCode >= 200 && res.statusCode < 300)) {
  return stop(502, { ok: false, error: `The register did not answer (HTTP ${res.statusCode}).` });
}
const rows = Array.isArray(res.body) ? res.body : [];
if (rows.length !== 1) {
  return stop(404, { ok: false, error: `No row in the booking register carries ${a.reference}.` });
}
const row = rows[0];
const notes = row.amendment_notes ?? "";
const line = a.note ? `PMS: ${a.note}` : null;

const patch = { booking_status: a.status };
if (a.confirmation) patch.hotel_conf_no = a.confirmation;
if (line && !notes.includes(line)) patch.amendment_notes = notes ? `${notes}\n${line}` : line;

return [{ json: {
  stop: false,
  patchUrl: `${a.registerUrl}?id=eq.${encodeURIComponent(row.id)}`,
  patch,
} }];

// PMS → CRS register: "Remember it"
// Mode: Run Once for All Items.
//
// Written: the answer's id is remembered, so the PMS's retry of the SAME
// answer is told "already written". Not written: nothing is remembered - the
// PMS's next try must really try.

const a = $("Read the answer").first().json;
const res = $input.first().json;
if (!(res.statusCode >= 200 && res.statusCode < 300)) {
  return [{ json: { statusCode: 502,
    answer: { ok: false, error: `The register refused the change (HTTP ${res.statusCode}).` } } }];
}
$getWorkflowStaticData("global").written ??= {};
$getWorkflowStaticData("global").written[a.messageId] = Date.now();
return [{ json: { statusCode: 200, answer: { ok: true } } }];
